'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { ChevronDown, Sparkles, Check, X } from 'lucide-react'
import { getModelosByAgente, type ModeloPeticao } from '@/lib/modelos-peticao'

interface Props {
  agentType: string
  onSelect: (descricao: string) => void
}

export function SeletorModelo({ agentType, onSelect }: Props) {
  const modelos = getModelosByAgente(agentType)
  const [open, setOpen] = useState(false)
  const [selected, setSelected] = useState<string | null>(null)

  if (modelos.length === 0) return null

  function handleSelect(m: ModeloPeticao) {
    setSelected(m.id)
    onSelect(m.descricao)
    setOpen(false)
  }

  function handleClear() {
    setSelected(null)
    onSelect('')
  }

  return (
    <div className="mb-2">
      <button type="button" onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all"
        style={{
          background: selected ? 'rgba(34,197,94,0.06)' : 'rgba(212,175,55,0.06)',
          border: `1px solid ${selected ? 'rgba(34,197,94,0.2)' : 'rgba(212,175,55,0.2)'}`,
        }}>
        <div className="flex items-center gap-2">
          <Sparkles size={14} color={selected ? '#22C55E' : '#D4AF37'} />
          <span className="text-sm font-medium"
            style={{ color: selected ? '#22C55E' : '#D4AF37' }}>
            {selected
              ? '✓ Modelo selecionado — clique para trocar'
              : `✨ Usar modelo pronto (${modelos.length} disponíveis)`}
          </span>
        </div>
        <ChevronDown size={14} color="#D4AF37"
          style={{ transform: open ? 'rotate(180deg)' : 'none', transition: '0.2s' }} />
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, height: 0, marginTop: 0 }}
            animate={{ opacity: 1, height: 'auto', marginTop: 6 }}
            exit={{ opacity: 0, height: 0, marginTop: 0 }}
            className="overflow-hidden rounded-xl"
            style={{ border: '1px solid #2A2A2A', background: '#080600' }}>
            <p className="text-[10px] px-4 py-2 border-b"
              style={{ color: '#444', borderColor: '#1A1A1A' }}>
              Clique para preencher o contexto automaticamente
            </p>
            {modelos.map((m, i) => (
              <motion.button key={m.id} type="button"
                onClick={() => handleSelect(m)}
                whileHover={{ backgroundColor: 'rgba(212,175,55,0.04)' }}
                className="w-full text-left px-4 py-3 transition-all"
                style={{
                  borderBottom: i < modelos.length - 1 ? '1px solid #111' : 'none',
                  background: selected === m.id ? 'rgba(212,175,55,0.07)' : 'transparent',
                }}>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-sm font-medium" style={{ color: '#D4AF37' }}>{m.label}</span>
                      {selected === m.id && (
                        <span className="text-[10px] px-2 py-0.5 rounded-full"
                          style={{ background: 'rgba(34,197,94,0.15)', color: '#22C55E' }}>
                          Selecionado
                        </span>
                      )}
                    </div>
                    <p className="text-xs leading-relaxed" style={{ color: '#555' }}>
                      {m.descricao.slice(0, 100)}...
                    </p>
                  </div>
                  {selected === m.id && <Check size={14} color="#22C55E" className="flex-shrink-0 mt-1" />}
                </div>
              </motion.button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {selected && !open && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}
            className="mt-1.5 flex items-center justify-between px-1">
            <p className="text-[10px]" style={{ color: '#444' }}>Modelo aplicado ao contexto</p>
            <button type="button" onClick={handleClear}
              className="flex items-center gap-1 text-[10px] hover:text-red-400 transition-colors"
              style={{ color: '#555' }}>
              <X size={11} /> Limpar
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}